{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Verapamil, the closest structural analogue sharing the dimethoxyphenethylamine and N-methyl-aminobutyl scaffold, showed 27% absolute oral bioavailability in healthy volunteers, directly supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C73"],
      "claim": "Tramadol, which shares the methoxyphenyl and tertiary amine pharmacophore, has about 70% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C68"],
      "claim": "Venlafaxine, a close analogue with a methoxyphenyl and tertiary amine, has 44% absolute oral bioavailability in healthy subjects, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Clomipramine, a tertiary amine drug with high permeability, has 48.2% absolute oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C72"],
      "claim": "Levosulpiride, a polar sulfonamide-containing analogue, still achieves 23.4% absolute oral bioavailability in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Bevantolol, sharing the 3,4-dimethoxyphenethylamine core, has mean absolute oral bioavailability of 57% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "One verapamil record in patients reports 12% oral bioavailability, below the 20% threshold, reflecting first-pass variability; however, most verapamil and analogue data are ≥20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue verapamil is borderline but mostly ≥20%, and multiple structurally related tertiary-amine/dimethoxyphenyl drugs (tramadol, venlafaxine, clomipramine, bevantolol) show clearly higher oral bioavailability; even polar sulfonamide analogues exceed 20%. Therefore F≥20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "The cyclic disulfone moiety is not represented in the evidence set; its effect on permeability and first-pass metabolism is uncertain.",
    "Verapamil data straddle the 20% threshold, so the closest-analogue prediction is sensitive to formulation and study conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

